def-hyp(
    Type.annotation(@A, Set(T@Set.ctxt.T)),
    Topology.closure(A),
    Set.sep-typed(
        @x,
        S@Topology.ctxt.S,
        Logic.forall-typed(
            @F,
            Set(T@Set.ctxt.T),
            Logic.implies(
                Logic.and(Topology.closedSet(F, τ@Topology.ctxt.tau, S@Topology.ctxt.S), Set.subset(A, F)),
                Set.mem(x, F)
            )
        )
    )
)
